# Generated by release/render.py for each release; do not edit by hand.
class Anonimize < Formula
  desc "Anonymize project folders before sharing them"
  homepage "$repo_url"
  version "$version"
  license "MIT"

  on_macos do
    on_arm do
      url "$arm_url"
      sha256 "$arm_sha256"
    end
    on_intel do
      url "$intel_url"
      sha256 "$intel_sha256"
    end
  end

  depends_on :macos
  # OCR for scanned PDF pages and .rar extraction; skip with
  # --without-tesseract / --without-unar.
  depends_on "tesseract" => :recommended
  depends_on "unar" => :recommended

  def install
    # PyInstaller onedir build: the program and its _internal folder.
    libexec.install Dir["*"]
    bin.write_exec_script libexec/"anonimize"
  end

  def caveats
    <<~EOS
      Check that the optional OCR and .rar tools were found:
        anonimize --check-tools
    EOS
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/anonimize --version")
  end
end
